pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        address payable receiver = payable(address(0xdead));
        vm.deal(receiver, 0);
        (bool ok, ) = address(c).call{value: 1 wei}("");
        require(ok, "transfer failed");
        assertEq(c.depositsCount(), 1);
    }
}
